'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/uniform' );
var floor = require( '@stdlib/math/base/special/floor' );
var pow = require( '@stdlib/math/base/special/pow' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var copy = require( '@stdlib/ndarray/copy' );
var zeros = require( '@stdlib/ndarray/zeros' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var format = require( '@stdlib/string/format' );
var rffti = require( '@stdlib/fft/base/fftpack/ndarray/generic/rffti' );
var pkg = require( './../package.json' ).name;
var rfftf = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'generic'
};
var nopts = {
	'dtype': 'int32'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} iter - number of iterations
* @param {PositiveInteger} N - sequence length
* @returns {Function} benchmark function
*/
function createBenchmark( iter, N ) {
	var len;
	var x;
	var w;
	var i;

	x = [];
	for ( i = 0; i < iter; i++ ) {
		x.push( uniform( [ N ], -100.0, 100.0, options ) );
	}
	len = scalar2ndarray( N, nopts );
	w = zeros( [ ( 2*N ) + 34 ], options );
	rffti( [ w, len ] );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var xc;
		var v;
		var i;

		xc = [];
		for ( i = 0; i < iter; i++ ) {
			xc.push( copy( x[ i ] ) );
		}
		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			v = rfftf( [ xc[ i ], w ] );
			if ( typeof v !== 'object' ) {
				b.fail( 'should return an ndarray' );
			}
		}
		b.toc();
		if ( isnan( v.get( i%N ) ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var lengths;
	var opts;
	var iter;
	var N;
	var f;
	var i;

	lengths = [
		8,
		16,
		32,
		64,
		128,
		256,
		512,
		1024
	];

	iter = 1e6;

	for ( i = 0; i < lengths.length; i++ ) {
		N = lengths[ i ];
		f = createBenchmark( iter, N );
		opts = {
			'iterations': iter
		};
		bench( format( '%s:N=%d', pkg, N ), opts, f );
		iter = floor( pow( iter, 3.0/4.0 ) );
	}
}

main();
